// ─── File: ArchGuardrailsDemo.java ───
// Runnable model of ArchUnit-style guardrails. In a real project these are
// ArchUnit JUnit tests (classes().that()...should()...) that run in `mvn test`.
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class ArchGuardrailsDemo {
    private static final Logger log = Logger.getLogger("ARCH");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // GOOD module: controller→service→repository, outbox relay, no remote call in tx.
        CodeModel good = new CodeModel();
        good.addClass("TransferController", List.of("TransferService"), false, false, false);
        good.addClass("TransferService",    List.of("TransferRepository"), true, false, false);
        good.addClass("TransferRepository",  List.of(), false, true, false);
        good.addClass("OutboxRelay",         List.of("OutboxRepository", "KafkaProducer"), false, true, true);

        // BAD module: controller calls repo; tx method calls remote client; dual write.
        CodeModel bad = new CodeModel();
        bad.addClass("QuickController",  List.of("TransferRepository"), false, false, false);     // layering break
        bad.addClass("TransferService", List.of("FraudClient", "TransferRepository"), true, false, false); // remote in tx
        bad.addClass("PaymentService",  List.of("PaymentRepository", "KafkaProducer"), true, false, false); // dual write
        bad.addClass("TransferRepository", List.of(), false, true, false);

        List<ArchRule> rules = List.of(
                new LayeringRule(), new NoRemoteCallInTransactionRule(), new NoDualWriteRule());
        RuleEngine engine = new RuleEngine(rules);

        log.info("=== Scanning GOOD module ===");
        engine.check(good);
        log.info("=== Scanning BAD module ===");
        engine.check(bad);
    }
}

// ─── model/CodeModel.java ───
class CodeModel {
    static class ClassInfo {
        final String name; final List<String> dependsOn;
        final boolean transactional, isRepository, isOutboxRelay;
        ClassInfo(String n, List<String> d, boolean tx, boolean repo, boolean relay) {
            name = n; dependsOn = d; transactional = tx; isRepository = repo; isOutboxRelay = relay;
        }
    }
    private final List<ClassInfo> classes = new ArrayList<>();
    void addClass(String n, List<String> deps, boolean tx, boolean repo, boolean relay) {
        classes.add(new ClassInfo(n, deps, tx, repo, relay));
    }
    List<ClassInfo> classes() { return classes; }
}

// ─── rules/ArchRule.java ───
interface ArchRule {
    String name();
    List<String> violations(CodeModel model);   // empty list = rule passes
}

// ─── rules/LayeringRule.java (controllers must not depend on repositories) ───
class LayeringRule implements ArchRule {
    public String name() { return "LAYERING"; }
    public List<String> violations(CodeModel model) {
        return model.classes().stream()
            .filter(c -> c.name.endsWith("Controller"))
            .filter(c -> c.dependsOn.stream().anyMatch(d -> d.endsWith("Repository")))
            .map(c -> c.name + " (Controller) depends directly on a Repository")
            .collect(Collectors.toList());
    }
}

// ─── rules/NoRemoteCallInTransactionRule.java ───
class NoRemoteCallInTransactionRule implements ArchRule {
    public String name() { return "NO_REMOTE_IN_TX"; }
    public List<String> violations(CodeModel model) {
        return model.classes().stream()
            .filter(c -> c.transactional)
            .filter(c -> c.dependsOn.stream().anyMatch(d -> d.endsWith("Client")))
            .map(c -> c.name + " is @Transactional and calls a remote *Client synchronously")
            .collect(Collectors.toList());
    }
}

// ─── rules/NoDualWriteRule.java ───
class NoDualWriteRule implements ArchRule {
    public String name() { return "NO_DUAL_WRITE"; }
    public List<String> violations(CodeModel model) {
        return model.classes().stream()
            .filter(c -> !c.isOutboxRelay)
            .filter(c -> c.dependsOn.stream().anyMatch(d -> d.endsWith("Repository"))
                      && c.dependsOn.stream().anyMatch(d -> d.contains("Kafka") || d.contains("Producer")))
            .map(c -> c.name + " writes to a Repository AND a broker without the OutboxRelay")
            .collect(Collectors.toList());
    }
}

// ─── engine/RuleEngine.java ───
class RuleEngine {
    private static final Logger log = Logger.getLogger("ARCH");
    private final List<ArchRule> rules;
    RuleEngine(List<ArchRule> rules) { this.rules = rules; }
    void check(CodeModel model) {
        boolean clean = true;
        for (ArchRule rule : rules) {
            List<String> v = rule.violations(model);
            if (v.isEmpty()) {
                log.info(() -> "Rule " + rule.name() + " PASSED");
            } else {
                clean = false;
                v.forEach(msg -> log.severe("Rule " + rule.name() + " VIOLATED: " + msg));
            }
        }
        if (clean) log.info("Build OK — architecture rules satisfied");
        else log.severe("Build FAILED — fix violations before merge");
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
